    case TOWN_STRONGHOLD:
        heroClass1 = 12;
        heroClass2 = 13;
        break;
    case TOWN_FORTRESS:
        heroClass1 = 14;
        heroClass2 = 15;
        break;
    case TOWN_CONFLUX:
        heroClass1 = 16;
        heroClass2 = 17;
        break;
