        if (outfile->Write(&shortValue, sizeof(shortValue)) < sizeof(shortValue))
            return -1;
        shortValue = ultimateArtifactY;
        if (outfile->Write(&shortValue, sizeof(shortValue)) < sizeof(shortValue))
            return -1;

